CREATE TABLE IF NOT EXISTS season_key_tbl (
    key_id              VARCHAR(15),
    season_key          BYTEA,
    signature           BYTEA,
    CONSTRAINT season$keyid$pk PRIMARY KEY (key_id)
);

COMMENT ON TABLE season_key_tbl IS 'stores season keys for license validation';
COMMENT ON COLUMN season_key_tbl.key_id IS 'key id to identify correct key from license';
COMMENT ON COLUMN season_key_tbl.season_key IS 'public season key used in verifying license';
COMMENT ON COLUMN season_key_tbl.signature IS 'signature of public key, verified via master key';

